387	    public void log(Claim claim, String user, LocalDate on, BigDecimal due) {
388	        jdbc.update("INSERT INTO claim_log (sheet_id, claim_id, status, by_user, logged_on, due) VALUES (?, ?, ?, ?, ?, ?)",
389	                claim.sheetId(), claim.id(), claim.status().name(), user, Date.valueOf(on),
390	                due == null ? "n/a" : due.toPlainString());
391	    }
