393	    /** Adds a comment to the claim: {@code text}, written by {@code user} on {@code on}. */
394	    public void comment(Claim claim, String user, LocalDate on, String text) {
395	        jdbc.update("INSERT INTO claim_comment (sheet_id, claim_id, by_user, commented_on, text) VALUES (?, ?, ?, ?, ?)",
396	                claim.sheetId(), claim.id(), user, Date.valueOf(on), text);
397	    }
