405	    /** The claim's lines, in the order added. */
406	    public List<ClaimLine> lines(Claim claim) {
407	        return jdbc.query("SELECT * FROM " + AsOf.table("claim_line") + " WHERE claim_id = ? ORDER BY id",
408	                (rs, n) -> new ClaimLine(rs.getString("label"), rs.getInt("qty"), rs.getBigDecimal("unit").setScale(2)),
409	                claim.id());
