412	    /** The lines of the sheet's claims, by claim id, each in the order added as "label qty x unit". */
413	    public java.util.Map<Long, List<String>> lines(String sheetId) {
414	        java.util.Map<Long, List<String>> lines = new java.util.HashMap<>();
415	        jdbc.query("SELECT * FROM " + AsOf.table("claim_line") + " WHERE sheet_id = ? ORDER BY id", rs -> {
416	            lines.computeIfAbsent(rs.getLong("claim_id"), k -> new java.util.ArrayList<>())
417	                    .add(new ClaimLine(rs.getString("label"), rs.getInt("qty"), rs.getBigDecimal("unit").setScale(2)).shown());
418	        }, sheetId);
