422	    /** The comments of the sheet's claims, by claim id, each oldest first as "user on date: text". */
423	    public java.util.Map<Long, List<String>> comments(String sheetId) {
424	        java.util.Map<Long, List<String>> comments = new java.util.HashMap<>();
425	        jdbc.query("SELECT * FROM " + AsOf.table("claim_comment") + " WHERE sheet_id = ? ORDER BY id", rs -> {
