444	                "SELECT logged_on FROM " + AsOf.table("claim_log") + " WHERE claim_id = ? AND status = ? ORDER BY id DESC",
445	                (rs, n) -> rs.getObject("logged_on", LocalDate.class), claim.id(), ClaimStatus.DELETED.name());
