449	    /** The user each of the sheet's claims had its review last assigned to, by claim id (a claim never assigned is left out). */
450	    public java.util.Map<Long, String> reviewUsers(String sheetId) {
451	        java.util.Map<Long, String> users = new java.util.HashMap<>();
452	        jdbc.query("SELECT id, review_user FROM " + AsOf.table("claim") + " WHERE sheet_id = ? AND review_user IS NOT NULL", rs -> {
