464	    /** The sheet's today on which each of the sheet's claims last went to REVIEW, by claim id (a claim that never did is left out). */
465	    public java.util.Map<Long, LocalDate> reviewOns(String sheetId) {
466	        java.util.Map<Long, LocalDate> on = new java.util.HashMap<>();
467	        jdbc.query("SELECT claim_id, logged_on FROM " + AsOf.table("claim_log") + " WHERE sheet_id = ? AND status = ? ORDER BY id", rs -> {
468	            on.put(rs.getLong("claim_id"), rs.getObject("logged_on", LocalDate.class));
