473	    /** The sheet's today on which each of the sheet's claims last went to PENDING, by claim id (a claim that never did is left out). */
474	    public java.util.Map<Long, LocalDate> pendingOns(String sheetId) {
475	        java.util.Map<Long, LocalDate> on = new java.util.HashMap<>();
476	        jdbc.query("SELECT claim_id, logged_on FROM " + AsOf.table("claim_log") + " WHERE sheet_id = ? AND status = ? ORDER BY id", rs -> {
477	            on.put(rs.getLong("claim_id"), rs.getObject("logged_on", LocalDate.class));
478	        }, sheetId, ClaimStatus.PENDING.name());
479	        return on;
480	    }
481	
482	    /** The status logs of the sheet's claims, by claim id, each oldest first as "STATUS by user on date due=due". */
483	    public java.util.Map<Long, List<String>> logs(String sheetId) {
484	        java.util.Map<Long, List<String>> logs = new java.util.HashMap<>();
485	        jdbc.query("SELECT * FROM " + AsOf.table("claim_log") + " WHERE sheet_id = ? ORDER BY id", rs -> {
486	            logs.computeIfAbsent(rs.getLong("claim_id"), k -> new java.util.ArrayList<>())
487	                    .add(rs.getString("status") + " by " + rs.getString("by_user") + " on "
488	                            + rs.getObject("logged_on", LocalDate.class) + " due=" + rs.getString("due"));
489	        }, sheetId);
490	        return logs;
491	    }
492	
493	    /**
494	     * Each logged claim's status at the end of {@code on}, by claim id: the last status its log records on or before it,
495	     * DRAFT (counting nowhere) when it was added after. A claim with no log is not in the map.
496	     */
497	    public java.util.Map<Long, ClaimStatus> statusesOn(String sheetId, LocalDate on) {
498	        java.util.Map<Long, ClaimStatus> statuses = new java.util.HashMap<>();
499	        jdbc.query("SELECT * FROM " + AsOf.table("claim_log") + " WHERE sheet_id = ? ORDER BY id", rs -> {
500	            long id = rs.getLong("claim_id");
501	            if (!rs.getObject("logged_on", LocalDate.class).isAfter(on)) {
502	                statuses.put(id, ClaimStatus.valueOf(rs.getString("status")));
503	            } else {
504	                statuses.putIfAbsent(id, ClaimStatus.DRAFT);
505	            }
506	        }, sheetId);
507	        return statuses;
508	    }
509	
510	    /**
511	     * Binds the person's claims to the figures of a statement: each claim in {@code figures} is stated at
512	     * its figure (null: n/a), and every other claim of theirs is left unbound.
513	     */
514	    public void bind(String sheetId, long personId, java.util.Map<Long, BigDecimal> figures) {
515	        jdbc.update("UPDATE claim SET stated = FALSE, stated_due = NULL WHERE sheet_id = ? AND person_id = ?",
516	                sheetId, personId);
517	        figures.forEach((id, figure) -> jdbc.update(
518	                "UPDATE claim SET stated = TRUE, stated_due = ? WHERE id = ?", figure, id));
519	    }
520	
521	    /**
522	     * The sheet's today on which each claim of the sheet was first logged OPEN, by claim id; a claim never logged OPEN
523	     * is not in the map.
524	     */
525	    public Map<Long, LocalDate> openedOn(String sheetId) {
526	        Map<Long, LocalDate> opened = new java.util.HashMap<>();
527	        jdbc.query("SELECT claim_id, logged_on FROM claim_log WHERE sheet_id = ? AND status = ? ORDER BY id",
528	                rs -> {
529	                    opened.putIfAbsent(rs.getLong(1), rs.getObject(2, LocalDate.class));
530	                }, sheetId, ClaimStatus.OPEN.name());
531	        return opened;
532	    }
533	
534	    /**
535	     * The next number of {@code scope} on the sheet, as {@link #changeStatus} numbers a settled claim due by
536	     * {@code dueBy} (null: sheet-wide, FY<yyyy>-<n> in the fiscal year {@code dueBy} falls in).
537	     */
538	    public String number(String sheetId, String scope, LocalDate dueBy) {
539	        if (scope == null) {
540	            String fiscalYear = fiscalYear(sheetId, dueBy);
541	            return fiscalYear + "-" + nextNumber(sheetId, fiscalYear);
542	        }
543	        return (scope.isEmpty() ? "X" : scope) + "-" + nextPeriodNumber(sheetId, scope);
544	    }
545	
546	    /**
547	     * The fiscal year (FY<yyyy>) the date falls in on the sheet: FY<yyyy> starts on the first of the sheet's fiscal
548	     * start month (January when it has none) in yyyy.
549	     */
550	    private String fiscalYear(String sheetId, LocalDate date) {
551	        List<String> values = jdbc.queryForList("SELECT setting_value FROM setting WHERE sheet_id = ? AND setting_key = ?",
552	                String.class, sheetId, "fiscal-start-month");
553	        String value = values.isEmpty() || values.get(0) == null ? "" : values.get(0).trim();
554	        int start = value.isEmpty() ? 1 : Integer.parseInt(value);
555	        return "FY" + (date.getMonthValue() >= start ? date.getYear() : date.getYear() - 1);
556	    }
557	
558	    /**
559	     * The sheet's next claim number in the fiscal year: one after the last number given in that fiscal year anywhere
560	     * in the sheet's tree, which share one sequence. The tree's counter rows are locked (in sheet order) by the
561	     * increment until the transaction commits, so two claims opened at once anywhere in the tree get different numbers.
562	     */
563	    private long nextNumber(String sheetId, String fiscalYear) {
564	        Set<String> tree = new TreeSet<>(people.tree(sheetId));
565	        for (String sheet : tree) {
566	            try {
567	                jdbc.update("INSERT INTO claim_fiscal_number_seq (sheet_id, fiscal_year, last_number) SELECT ?, ?, 0 "
568	                        + "WHERE NOT EXISTS (SELECT 1 FROM claim_fiscal_number_seq WHERE sheet_id = ? AND fiscal_year = ?)",
569	                        sheet, fiscalYear, sheet, fiscalYear);
570	            } catch (DuplicateKeyException e) {
571	                // Another user started the sheet's counter at the same moment.
572	            }
573	        }
574	        long last = 0;
575	        for (String sheet : tree) {
576	            jdbc.update("UPDATE claim_fiscal_number_seq SET last_number = last_number WHERE sheet_id = ? AND fiscal_year = ?",
577	                    sheet, fiscalYear);
578	            last = Math.max(last, jdbc.queryForObject(
579	                    "SELECT last_number FROM claim_fiscal_number_seq WHERE sheet_id = ? AND fiscal_year = ?",
580	                    Long.class, sheet, fiscalYear));
581	        }
582	        jdbc.update("UPDATE claim_fiscal_number_seq SET last_number = ? WHERE sheet_id = ? AND fiscal_year = ?",
583	                last + 1, sheetId, fiscalYear);
584	        return last + 1;
585	    }
586	
587	    /** The next number of the sheet's sequence for the period ("" for no period); locked like {@link #nextNumber}. */
588	    private long nextPeriodNumber(String sheetId, String scope) {
589	        try {
590	            jdbc.update("INSERT INTO claim_period_number_seq (sheet_id, scope, last_number) SELECT ?, ?, 0 "
591	                    + "WHERE NOT EXISTS (SELECT 1 FROM claim_period_number_seq WHERE sheet_id = ? AND scope = ?)",
592	                    sheetId, scope, sheetId, scope);
593	        } catch (DuplicateKeyException e) {
594	            // Another user started the period's counter at the same moment.
595	        }
596	        jdbc.update("UPDATE claim_period_number_seq SET last_number = last_number + 1 WHERE sheet_id = ? AND scope = ?",
597	                sheetId, scope);
598	        return jdbc.queryForObject("SELECT last_number FROM claim_period_number_seq WHERE sheet_id = ? AND scope = ?",
599	                Long.class, sheetId, scope);
600	    }
601	}
