130	    /**
131	     * The sheets of the sheet's tree: the sheet itself, its ancestors (its parent, their parent and so on) and its
132	     * descendants (the sheets naming it as their parent, their children and so on), each once. Not dated, like the parent.
133	     */
134	    public Set<String> tree(String sheetId) {
135	        Set<String> tree = new LinkedHashSet<>(List.of(sheetId));
136	        String at = sheetId;
137	        while (true) {
138	            List<String> parent = jdbc.queryForList("SELECT setting_value FROM setting WHERE sheet_id = ? AND setting_key = 'parent'",
139	                    String.class, at);
140	            if (parent.isEmpty() || parent.get(0).isBlank() || !tree.add(parent.get(0).trim())) {
141	                break;
142	            }
143	            at = parent.get(0).trim();
144	        }
145	        Deque<String> todo = new ArrayDeque<>(List.of(sheetId));
146	        while (!todo.isEmpty()) {
147	            for (String child : jdbc.queryForList("SELECT sheet_id FROM setting WHERE setting_key = 'parent' AND setting_value = ?",
148	                    String.class, todo.pop())) {
149	                if (tree.add(child)) {
150	                    todo.add(child);
151	                }
152	            }
153	        }
154	        return tree;
155	    }
