157	    /** The lower-cased names and aliases of everyone on the sheet's tree but the person {@code exceptId}. */
158	    private Set<String> namesInTree(String sheetId, long exceptId) {
159	        Set<String> names = new HashSet<>();
160	        for (String sheet : tree(sheetId)) {
161	            names.addAll(jdbc.queryForList("SELECT LOWER(name) FROM " + AsOf.table("person") + " WHERE sheet_id = ? AND id <> ?",
162	                    String.class, sheet, exceptId));
163	            names.addAll(jdbc.queryForList("SELECT LOWER(alias) FROM " + AsOf.table("person_alias") + " WHERE sheet_id = ? AND person_id <> ?",
164	                    String.class, sheet, exceptId));
165	        }
166	        return names;
167	    }
