199	    /**
200	     * The ids of the sheet's people who clash: whose name or any alias is a name or alias of someone else on the sheet's
201	     * tree, ignoring case (people who were on the sheet before a name was refused across its tree).
202	     */
203	    public Set<Long> clashing(String sheetId) {
204	        Map<String, Set<Long>> users = new HashMap<>();
205	        for (String sheet : tree(sheetId)) {
206	            jdbc.query("SELECT id, LOWER(name) FROM " + AsOf.table("person") + " WHERE sheet_id = ?",
207	                    rs -> { users.computeIfAbsent(rs.getString(2), k -> new HashSet<>()).add(rs.getLong(1)); }, sheet);
208	            jdbc.query("SELECT person_id, LOWER(alias) FROM " + AsOf.table("person_alias") + " WHERE sheet_id = ?",
209	                    rs -> { users.computeIfAbsent(rs.getString(2), k -> new HashSet<>()).add(rs.getLong(1)); }, sheet);
210	        }
211	        Set<Long> own = new HashSet<>(jdbc.queryForList("SELECT id FROM " + AsOf.table("person") + " WHERE sheet_id = ?", Long.class, sheetId));
212	        Set<Long> clashing = new HashSet<>();
213	        users.values().stream().filter(ids -> ids.size() > 1).forEach(ids -> ids.stream().filter(own::contains).forEach(clashing::add));
214	        return clashing;
215	    }
