301	    /**
302	     * Merge the person {@code from} into {@code into}: from's claims move to into (numbers, dates and the figures a
303	     * statement bound them to kept, listed after into's claims in the order they were added); from's statements become
304	     * into's (into's last statement stays their last; having none, from's last becomes it); from's name and aliases
305	     * become into's aliases; from's patrons are added to into's and anyone naming from names into instead (never
306	     * themselves, no repeats); from's pool memberships and closed-period figures move to into (added to into's own where
307	     * into has one), and so do from's opening balances, plans and crews (a crew from leads is led by into). from's holds, watchers, grades and contact are dropped, and from leaves the sheet.
308	     * The merge is kept, made by {@code by} on the sheet-today {@code on}, so that {@link #undoMerge} can undo it.
309	     */
310	    public void merge(String sheetId, long from, long into, String by, LocalDate on) {
311	        long kept = keepMerge(sheetId, from, into, by, on);
312	        for (Long claim : jdbc.queryForList("SELECT id FROM claim WHERE person_id = ? ORDER BY listed, id", Long.class, from)) {
313	            jdbc.update("UPDATE claim SET person_id = ?, listed = "
314	                    + "(SELECT COALESCE(MAX(listed), 0) + 1 FROM claim WHERE sheet_id = ?) WHERE id = ?", into, sheetId, claim);
315	        }
316	        String name = jdbc.queryForObject("SELECT name FROM person WHERE id = ?", String.class, from);
317	        jdbc.update("UPDATE person_alias SET person_id = ? WHERE person_id = ?", into, from);
318	        for (Long patron : jdbc.queryForList("SELECT patron_id FROM person_patron WHERE person_id = ? ORDER BY named", Long.class, from)) {
319	            linkPatron(into, patron);
320	        }
321	        for (Long person : jdbc.queryForList("SELECT person_id FROM person_patron WHERE patron_id = ?", Long.class, from)) {
322	            linkPatron(person, into);
323	        }
324	        jdbc.update("DELETE FROM person_patron WHERE person_id = ? OR patron_id = ?", from, from);
325	        for (Map<String, Object> m : jdbc.queryForList("SELECT pool_name, share FROM pool_member WHERE sheet_id = ? AND person_id = ?",
326	                sheetId, from)) {
327	            if (jdbc.update("UPDATE pool_member SET share = share + ? WHERE sheet_id = ? AND pool_name = ? AND person_id = ?",
328	                    m.get("share"), sheetId, m.get("pool_name"), into) == 0) {
329	                jdbc.update("UPDATE pool_member SET person_id = ? WHERE sheet_id = ? AND pool_name = ? AND person_id = ?",
330	                        into, sheetId, m.get("pool_name"), from);
331	            }
332	        }
333	        jdbc.update("DELETE FROM pool_member WHERE sheet_id = ? AND person_id = ?", sheetId, from);
334	        // from's crews become into's: the crews from leads are led by into (into no longer a member of them), and
335	        // from's crew memberships move to into where into is neither in nor leading that crew.
336	        jdbc.update("DELETE FROM crew_member WHERE sheet_id = ? AND person_id = ? AND crew_name IN"
337	                + " (SELECT name FROM crew WHERE sheet_id = ? AND lead_id = ?)", sheetId, into, sheetId, from);
338	        jdbc.update("UPDATE crew SET lead_id = ? WHERE sheet_id = ? AND lead_id = ?", into, sheetId, from);
339	        jdbc.update("UPDATE crew_member SET person_id = ? WHERE sheet_id = ? AND person_id = ?"
340	                + " AND crew_name NOT IN (SELECT crew_name FROM crew_member WHERE sheet_id = ? AND person_id = ?)"
341	                + " AND crew_name NOT IN (SELECT name FROM crew WHERE sheet_id = ? AND lead_id = ?)",
342	                into, sheetId, from, sheetId, into, sheetId, into);
343	        jdbc.update("DELETE FROM crew_member WHERE sheet_id = ? AND person_id = ?", sheetId, from);
344	        for (Map<String, Object> m : jdbc.queryForList("SELECT period_name, total, carried FROM period_person_total WHERE sheet_id = ? AND person_id = ?",
345	                sheetId, from)) {
346	            if (jdbc.update("UPDATE period_person_total SET total = total + ?, carried = carried + ? WHERE sheet_id = ? AND period_name = ? AND person_id = ?",
347	                    m.get("total"), m.get("carried"), sheetId, m.get("period_name"), into) == 0) {
348	                jdbc.update("UPDATE period_person_total SET person_id = ? WHERE sheet_id = ? AND period_name = ? AND person_id = ?",
349	                        into, sheetId, m.get("period_name"), from);
350	            }
351	        }
352	        jdbc.update("DELETE FROM period_person_total WHERE sheet_id = ? AND person_id = ?", sheetId, from);
353	        for (Map<String, Object> m : jdbc.queryForList("SELECT period_name, amount FROM period_person_opening WHERE sheet_id = ? AND person_id = ?",
354	                sheetId, from)) {
355	            if (jdbc.update("UPDATE period_person_opening SET amount = amount + ? WHERE sheet_id = ? AND period_name = ? AND person_id = ?",
356	                    m.get("amount"), sheetId, m.get("period_name"), into) == 0) {
357	                jdbc.update("INSERT INTO period_person_opening (sheet_id, period_name, person_id, amount) VALUES (?, ?, ?, ?)",
358	                        sheetId, m.get("period_name"), into, m.get("amount"));
359	            }
360	        }
361	        jdbc.update("DELETE FROM period_person_opening WHERE sheet_id = ? AND person_id = ?", sheetId, from);
362	        jdbc.update("UPDATE plan SET person_id = ? WHERE person_id = ?", into, from);
363	        takeStatements(sheetId, from, into);
364	        jdbc.update("DELETE FROM person_hold WHERE person_id = ?", from);
365	        jdbc.update("DELETE FROM person_retirement WHERE person_id = ?", from);
366	        jdbc.update("DELETE FROM person_snapshot WHERE person_id = ?", from);
367	        jdbc.update("DELETE FROM person_watch WHERE person_id = ?", from);
368	        jdbc.update("DELETE FROM person_grade WHERE person_id = ?", from);
369	        jdbc.update("DELETE FROM person_terms WHERE person_id = ?", from);
370	        jdbc.update("DELETE FROM person WHERE id = ?", from);
371	        alias(sheetId, into, name);
372	        jdbc.update("INSERT INTO person_merge_alias (merge_id, alias_id) SELECT ?, MAX(id) FROM person_alias WHERE person_id = ?",
373	                kept, into);
374	    }
