376	    /** Keep the merge of {@code from} into {@code into} as from is before it, returning its id. */
377	    private long keepMerge(String sheetId, long from, long into, String by, LocalDate on) {
378	        KeyHolder key = new GeneratedKeyHolder();
379	        jdbc.update(con -> {
380	            PreparedStatement ps = con.prepareStatement(
381	                    "INSERT INTO person_merge (sheet_id, into_id, from_id, name, grade, terms, contact, tags, origin_sheet_id, "
382	                            + "origin_name, transferred_on, merged_by, merged_on) SELECT sheet_id, ?, id, name, grade, terms, contact, "
383	                            + "tags, origin_sheet_id, origin_name, transferred_on, ?, ? FROM person WHERE id = ?", new String[] { "id" });
384	            ps.setLong(1, into);
385	            ps.setString(2, by);
386	            ps.setDate(3, Date.valueOf(on));
387	            ps.setLong(4, from);
388	            return ps;
389	        }, key);
390	        long kept = key.getKey().longValue();
391	        jdbc.update("INSERT INTO person_merge_claim (merge_id, claim_id) SELECT ?, id FROM claim WHERE person_id = ?", kept, from);
392	        jdbc.update("INSERT INTO person_merge_alias (merge_id, alias_id) SELECT ?, id FROM person_alias WHERE person_id = ?", kept, from);
393	        jdbc.update("INSERT INTO person_merge_grade (merge_id, from_date, grade) SELECT ?, from_date, grade FROM person_grade "
394	                + "WHERE person_id = ?", kept, from);
395	        jdbc.update("INSERT INTO person_merge_terms (merge_id, from_date, terms) SELECT ?, from_date, terms FROM person_terms "
396	                + "WHERE person_id = ?", kept, from);
397	        return kept;
398	    }
