450	    /**
451	     * Transfer the person to the sheet {@code to} as {@link #transfer(Person, String, Map)} does, merged on arrival
452	     * into the person {@code into} there when given (as {@link #merge(String, long, long)} does): their claims go to
453	     * {@code into} (listed after theirs), their statements become {@code into}'s (whose last statement stays their last,
454	     * or, having none, becomes the transferred person's last), their name and aliases become {@code into}'s aliases, and
455	     * their grades and contact are dropped. Returns the id of the person they arrived as.
456	     */
457	    public long transfer(Person person, String to, Map<Long, String> numbers, Long into) {
458	        long from = person.id();
459	        long arrived = into != null ? into : arrive(person, to);
460	        jdbc.update("INSERT INTO person_alias (person_id, sheet_id, alias) SELECT ?, ?, alias FROM person_alias "
461	                + "WHERE person_id = ? ORDER BY id", arrived, to, from);
462	        List<Long> claims = jdbc.queryForList("SELECT id FROM claim WHERE person_id = ? ORDER BY listed, id", Long.class, from);
463	        for (Long claim : claims) {
464	            KeyHolder claimKey = new GeneratedKeyHolder();
465	            jdbc.update(con -> {
466	                PreparedStatement ps = con.prepareStatement(
467	                        "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note, status, claim_number, settled_due, "
468	                                + "opened_by, corrects, due_by, deferred_until, proofs, proofs_photo, split_from, late_entry, reminded_on, escalated, waived, tags, "
469	                                + "void_reason, edited_by, due_terms, stated, stated_due, listed) "
470	                                + "SELECT ?, ?, amount, claim_date, note, status, ?, settled_due, opened_by, corrects, due_by, "
