498	        jdbc.update("DELETE FROM person_patron WHERE person_id = ? OR patron_id = ?", from, from);
499	        jdbc.update("DELETE FROM pool_member WHERE sheet_id = ? AND person_id = ?", person.sheetId(), from);
500	        jdbc.update("DELETE FROM plan_claim WHERE plan_id IN (SELECT id FROM plan WHERE person_id = ?)", from);
501	        jdbc.update("DELETE FROM plan_pause WHERE plan_id IN (SELECT id FROM plan WHERE person_id = ?)", from);
502	        jdbc.update("DELETE FROM plan_change WHERE plan_id IN (SELECT id FROM plan WHERE person_id = ?)", from);
503	        jdbc.update("DELETE FROM plan WHERE person_id = ?", from);
504	        jdbc.update("DELETE FROM period_person_total WHERE sheet_id = ? AND person_id = ?", person.sheetId(), from);
505	        jdbc.update("DELETE FROM period_person_opening WHERE sheet_id = ? AND person_id = ?", person.sheetId(), from);
506	        takeStatements(to, from, arrived);
