526	                    "INSERT INTO person (sheet_id, name, grade, terms, contact, tags, origin_sheet_id, origin_name, transferred_on, list_position) "
527	                            + "VALUES (?, ?, ?, ?, ?, ?, ?, ?, COALESCE((SELECT today_date FROM sheet WHERE id = ?), CURRENT_DATE), "
