130	    /** The sheet's children (the sheets naming it as their parent), their children and so on, each once, by id. Not dated, like the parent. */
131	    public List<String> descendants(String sheetId) {
132	        java.util.Set<String> seen = new java.util.TreeSet<>();
133	        java.util.Deque<String> todo = new java.util.ArrayDeque<>(List.of(sheetId));
134	        while (!todo.isEmpty()) {
135	            for (String child : jdbc.queryForList("SELECT sheet_id FROM setting WHERE setting_key = ? AND setting_value = ?",
136	                    String.class, PARENT, todo.pop())) {
137	                if (!child.equals(sheetId) && seen.add(child)) {
138	                    todo.add(child);
139	                }
140	            }
141	        }
142	        return List.copyOf(seen);
143	    }
