419	    /**
420	     * How the claim's live figures round: by the rounding mode in force on its date when there is one, else half up when it is
421	     * dated before the policy date, half to even on or after it. A correction rounds by the date of the claim it corrects.
422	     */
423	    public RoundingMode rounding(Claim claim) {
424	        LocalDate date = claim.date();
425	        if (claim.isCorrection() && claim.corrects() != null) {
426	            Claim corrected = claims.findByNumber(claim.sheetId(), claim.personId(), claim.corrects());
427	            if (corrected != null) {
428	                date = corrected.date();
429	            }
430	        }
431	        String mode = on(claim.sheetId(), ROUNDING, date);
432	        if (!mode.isEmpty()) {
433	            return mode.equals("half-up") ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
434	        }
435	        return date.isBefore(policyDate(claim.sheetId())) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
436	    }
