443	    /**
444	     * A claim's live due from its rate figure: the figure raised to the floor in force on the claim's date ({@link #floored}), then its
445	     * late charge, worked out on that floored figure, added on top. An open (OPEN or PENDING) claim whose due-by (fixed when it was made) plus
446	     * its grade's grace ({@link #overdueFrom}) is before {@code today} gains, for every full 30 days it is overdue, the late percent in force on
447	     * that boundary date (the due-by plus the grace plus 30, 60, 90 ... days)
448	     * of the figure plus the charges of the boundaries before it (compounding), each charge rounded by {@link #rounding}, the charges added up; a boundary whose percent is 0.00 adds nothing.
449	     * The charge follows the sheet's today; a statement binds the due this works out (callers use the bound due as it is); null (no figure) stays null.
450	     * A correction has no late charge and no floor, and a deferred claim no late charge (it is not overdue until the sheet's today reaches its date).
451	     * A waived claim has no late charge, whatever its overdue state.
452	     */
453	    public BigDecimal withLate(Claim claim, BigDecimal figure, LocalDate today) {
454	        return lateAdded(claim, floored(claim, figure), today);
455	    }
456	
457	    /** The (floored) figure with the claim's late charge on {@code today} added on top (see {@link #withLate}). */
458	    private BigDecimal lateAdded(Claim claim, BigDecimal figure, LocalDate today) {
459	        if (figure == null || !claim.status().isOpen() || claim.isCorrection() || claim.deferredOn(today) || claim.waived()) {
460	            return figure;
461	        }
462	        LocalDate dueBy = overdueFrom(claim);
463	        if (!dueBy.isBefore(today)) {
464	            return figure;
465	        }
466	        long periods = ChronoUnit.DAYS.between(dueBy, today) / 30;
467	        RoundingMode rounding = rounding(claim);
468	        BigDecimal total = figure;
469	        for (long n = 1; n <= periods; n++) {
470	            BigDecimal pct = latePct(claim.sheetId(), dueBy.plusDays(30 * n));
471	            if (pct.signum() != 0) {
472	                total = total.add(total.multiply(pct).movePointLeft(2).setScale(2, rounding));
473	            }
474	        }
475	        return total;
476	    }
477	
478	    /** The claim's rate figure raised to the floor in force on the claim's date; null (no due) stays null, and a correction's due has no floor. */
479	    public BigDecimal floored(Claim claim, BigDecimal due) {
480	        return due == null || claim.isCorrection() ? due : due.max(floor(claim.sheetId(), claim.date()));
481	    }
482	
483	    /** The key an action's permitted roles are kept under: perm-<action>. */
484	    public static String permKey(String action) {
485	        return "perm-" + action;
486	    }
487	
488	    /** The roles an action is permitted to, as saved: a comma separated list, or "" for the standing rule. */
489	    public String perm(String sheetId, String action) {
490	        return get(sheetId, permKey(action));
491	    }
492	
493	    /** The standing rule: reassign and reopen by steward; open, settle, void, close and today by clerk and steward (anyone but a viewer). */
494	    private static List<String> standing(String action) {
495	        return action.equals("reassign") || action.equals("reopen") ? List.of(STEWARD) : ROLES;
496	    }
497	
498	    /** Whether the user's role may take the action on the sheet: as the permission matrix has it, else by the standing rule. */
499	    public boolean permits(String sheetId, String action, String user) {
500	        String saved = perm(sheetId, action);
501	        List<String> roles = saved.isEmpty() ? standing(action) : List.of(saved.split(","));
502	        String role = role(sheetId, user);
503	        // A restricted user may do what a clerk may: the role narrows only the people list they see.
504	        return roles.contains(RESTRICTED.equals(role) ? CLERK : role);
505	    }
506	
507	    /** The sheet's roles, by user name. */
508	    public List<Role> roles(String sheetId) {
509	        return jdbc.query("SELECT * FROM " + AsOf.table("sheet_role") + " WHERE sheet_id = ? ORDER BY user_name",
510	                (rs, n) -> new Role(rs.getString("sheet_id"), rs.getString("user_name"), rs.getString("role")), sheetId);
511	    }
512	
513	    /** The role the user acts in: steward while the sheet's today is inside a delegation to them, else the role the sheet gave them. */
514	    public String role(String sheetId, String user) {
515	        return delegator(sheetId, user) != null ? STEWARD : givenRole(sheetId, user);
516	    }
517	
518	    /** The steward who delegated the steward role to the user for the sheet's today; null when none did. */
519	    public String delegator(String sheetId, String user) {
520	        return delegator(sheetId, user, sheets.today(sheetId));
521	    }
522	
523	    /** The steward who delegated the steward role to the user for {@code on}; null when none did. */
524	    public String delegator(String sheetId, String user, java.time.LocalDate on) {
525	        String name = user == null ? "" : user.trim();
526	        return name.isEmpty() ? null : delegations.delegator(sheetId, name, on);
527	    }
528	
529	    /** The role the sheet gave the user: clerk unless it gave them another (a delegation aside). */
530	    public String givenRole(String sheetId, String user) {
531	        List<String> roles = jdbc.queryForList("SELECT role FROM " + AsOf.table("sheet_role") + " WHERE sheet_id = ? AND user_name = ?",
532	                String.class, sheetId, user);
533	        return roles.isEmpty() ? CLERK : roles.get(0);
534	    }
535	
536	    /** Whether the user is a viewer on the sheet, and so may change nothing. */
537	    public boolean isViewer(String sheetId, String user) {
538	        return VIEWER.equals(role(sheetId, user == null ? "" : user.trim()));
539	    }
540	
541	    public void save(Role role) {
542	        jdbc.update("MERGE INTO sheet_role (sheet_id, user_name, role) KEY (sheet_id, user_name) VALUES (?, ?, ?)",
543	                role.sheetId(), role.user(), role.role());
544	    }
545	}
546	package net.officefloor.hq.app.claim;
547	
548	/**
549	 * Where a claim is in its life: DRAFT, then OPEN, then SETTLED; a DRAFT, OPEN or PENDING claim can be VOID, and a
550	 * SETTLED one too, by a steward within {@link #VOID_SETTLED_DAYS} days of its settlement. A clerk's
551	 * settle of a claim whose due is above the clerk limit makes it PENDING instead, until a steward approves it (SETTLED)
552	 * or rejects it (back to OPEN). A DRAFT claim can be DELETED, counting nowhere, and restored to DRAFT on the same
553	 * sheet's today it was deleted. Opening a DRAFT claim whose due is above the review threshold in force on its date makes it
554	 * REVIEW instead, counting in no total, until a steward's review makes it OPEN; a REVIEW claim can be VOID.
555	 */
556	public enum ClaimStatus {
557	    DRAFT, OPEN, PENDING, SETTLED, VOID, DELETED, REVIEW;
558	
559	    /** How many days after its settlement (by the sheet's today) a steward may still void a SETTLED claim. */
560	    public static final int VOID_SETTLED_DAYS = 7;
561	
562	    /** Whether a claim in this status may move to {@code next}. */
563	    public boolean allows(ClaimStatus next) {
564	        return switch (next) {
565	            case OPEN -> this == DRAFT || this == PENDING || this == REVIEW;
566	            case PENDING -> this == OPEN;
567	            case SETTLED -> this == OPEN || this == PENDING;
568	            case VOID -> this == DRAFT || this == OPEN || this == PENDING || this == SETTLED || this == REVIEW;
569	            case REVIEW -> this == DRAFT;
570	            case DRAFT -> this == DELETED;
571	            case DELETED -> this == DRAFT;
572	        };
573	    }
574	
575	    /** Whether a claim in this status is open: OPEN, or PENDING, which is handled like OPEN in every total. */
576	    public boolean isOpen() {
577	        return this == OPEN || this == PENDING;
578	    }
579	
580	    /** Whether a claim in this status counts toward the totals: an open or a SETTLED one. */
581	    public boolean counts() {
582	        return isOpen() || this == SETTLED;
583	    }
584	
585	    /** The audit event of a change from {@code from} to this status. */
586	    public String event(ClaimStatus from) {
587	        if (from == DELETED && this == DRAFT) {
588	            return "CLAIM_RESTORED";
589	        }
590	        if (from == REVIEW && this == OPEN) {
591	            return "CLAIM_REVIEWED";
592	        }
593	        if (from == PENDING) {
594	            return this == SETTLED ? "CLAIM_APPROVED" : this == OPEN ? "CLAIM_REJECTED" : event();
595	        }
596	        return event();
597	    }
598	
599	    /** The audit event of a change to this status. */
600	    public String event() {
601	        return switch (this) {
602	            case OPEN -> "CLAIM_OPENED";
603	            case PENDING -> "CLAIM_PENDING";
604	            case SETTLED -> "CLAIM_SETTLED";
605	            case VOID -> "CLAIM_VOIDED";
606	            case DRAFT -> "CLAIM_DRAFTED";
607	            case DELETED -> "CLAIM_DELETED";
608	            case REVIEW -> "CLAIM_REVIEW";
609	        };
610	    }
611	}
612	package net.officefloor.hq.app.claim;
613	
614	import java.math.BigDecimal;
615	import java.time.LocalDate;
616	
617	/**
618	 * A claim made by a person on a sheet. {@code amount} is 0.00 or more, in two decimals. {@code number}
619	 * is given when the claim is settled or approved, and kept by a void (null before; a claim numbered on opening before keeps its number). {@code settledDue} is the due fixed
620	 * when it was settled (null when not settled, or settled while no rate of its grade applied on its date).
621	 * {@code openedBy} is the user who opened it (null when never opened). {@code stated} is whether its person's
622	 * last statement bound it, at {@code statedDue} (null when it had no figure then). A claim with a negative amount is a
623	 * correction: {@code corrects} is the number of the SETTLED claim of the same person it corrects (null for any other claim).
624	 * {@code dueBy} is fixed when the claim is made, the terms-th business day after its date (see {@code Holidays#dueBy}), and kept when its terms or its date change later; a holiday added later on or before it works it out again from its date with the terms it was fixed with (see {@code Claims#refixDueBys}); one a steward set directly stays as set (see {@code Claims#setDueBy}).
625	 * {@code deferredUntil} is the date an OPEN claim was deferred to (null when never deferred).
626	 * {@code proofs} is how many proofs it has been given (0 for none), {@code proofsPhoto} how many of them are photos (the rest are receipts).
627	 * {@code splitFrom} is the number of the claim it was split off (null for any other claim).
628	 * {@code lateEntry} is whether it was added while the period its due-by falls in was soft-closed.
629	 * {@code remindedOn} is the last sheet's today a reminder was written for it (null when never reminded).
630	 * {@code ref} is its external reference, unique on the sheet without regard to case (null when it has none).
631	 * {@code tags} are its tags, trimmed, lower-cased, without repeats and sorted (empty for none).
632	 * {@code waived} is whether a steward waived its late charge: it bears none from then on.
633	 * {@code held} is whether it is held: while OPEN or PENDING and not bound by a statement it counts in no live due figure (it still counts in claimed).
634	 */
635	public record Claim(long id, String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
636	        ClaimStatus status, String number, BigDecimal settledDue, String openedBy, boolean stated,
637	        BigDecimal statedDue, String corrects, LocalDate dueBy, LocalDate deferredUntil, int proofs, int proofsPhoto,
638	        String splitFrom, boolean lateEntry, LocalDate remindedOn, String ref, java.util.List<String> tags, boolean waived, boolean held) {
639	
640	    public Claim with(ClaimInput input, LocalDate date) {
641	        return new Claim(id, sheetId, personId, input.amount(), date, input.note(), status, number, settledDue, openedBy, stated, statedDue, input.corrects(), dueBy, deferredUntil, proofs, proofsPhoto, splitFrom, lateEntry, remindedOn, input.ref(), input.tags(), waived, held);
642	    }
643	
644	    public Claim withStatus(ClaimStatus status, String number, BigDecimal settledDue, String openedBy) {
645	        return new Claim(id, sheetId, personId, amount, date, note, status, number, settledDue, openedBy, stated, statedDue, corrects, dueBy, deferredUntil, proofs, proofsPhoto, splitFrom, lateEntry, remindedOn, ref, tags, waived, held);
646	    }
647	
648	    /** The claim moved to another person: unbound from any statement, so live until their next one. */
649	    public Claim withPerson(long personId) {
650	        return new Claim(id, sheetId, personId, amount, date, note, status, number, settledDue, openedBy, false, null, corrects, dueBy, deferredUntil, proofs, proofsPhoto, splitFrom, lateEntry, remindedOn, ref, tags, waived, held);
651	    }
652	
653	    /** The claim re-dated to {@code date}, numbered {@code number}. */
654	    public Claim withDate(LocalDate date, String number) {
655	        return new Claim(id, sheetId, personId, amount, date, note, status, number, settledDue, openedBy, stated, statedDue, corrects, dueBy, deferredUntil, proofs, proofsPhoto, splitFrom, lateEntry, remindedOn, ref, tags, waived, held);
656	    }
657	
658	    /** The claim due by {@code dueBy}. */
659	    public Claim withDueBy(LocalDate dueBy) {
660	        return new Claim(id, sheetId, personId, amount, date, note, status, number, settledDue, openedBy, stated, statedDue, corrects, dueBy, deferredUntil, proofs, proofsPhoto, splitFrom, lateEntry, remindedOn, ref, tags, waived, held);
661	    }
662	
663	    /** The claim deferred to {@code until}. */
664	    public Claim withDeferredUntil(LocalDate until) {
665	        return new Claim(id, sheetId, personId, amount, date, note, status, number, settledDue, openedBy, stated, statedDue, corrects, dueBy, until, proofs, proofsPhoto, splitFrom, lateEntry, remindedOn, ref, tags, waived, held);
666	    }
667	
668	    /** The claim with {@code amount} as its amount, unbound from any statement (live until its person's next one). */
669	    public Claim withAmountUnbound(BigDecimal amount) {
670	        return new Claim(id, sheetId, personId, amount, date, note, status, number, settledDue, openedBy, false, null, corrects, dueBy, deferredUntil, proofs, proofsPhoto, splitFrom, lateEntry, remindedOn, ref, tags, waived, held);
671	    }
672	
673	    /** The claim with {@code proofs} proofs, {@code proofsPhoto} of them photos. */
674	    public Claim withProofs(int proofs, int proofsPhoto) {
675	        return new Claim(id, sheetId, personId, amount, date, note, status, number, settledDue, openedBy, stated, statedDue, corrects, dueBy, deferredUntil, proofs, proofsPhoto, splitFrom, lateEntry, remindedOn, ref, tags, waived, held);
676	    }
677	
678	    /** The claim with its late charge waived. */
679	    public Claim withWaived() {
680	        return new Claim(id, sheetId, personId, amount, date, note, status, number, settledDue, openedBy, stated, statedDue, corrects, dueBy, deferredUntil, proofs, proofsPhoto, splitFrom, lateEntry, remindedOn, ref, tags, true, held);
681	    }
682	
683	    /** The claim held ({@code held} true) or released. */
684	    public Claim withHeld(boolean held) {
685	        return new Claim(id, sheetId, personId, amount, date, note, status, number, settledDue, openedBy, stated, statedDue, corrects, dueBy, deferredUntil, proofs, proofsPhoto, splitFrom, lateEntry, remindedOn, ref, tags, waived, held);
686	    }
687	
688	    /** The claim reminded on {@code on}. */
689	    public Claim withRemindedOn(LocalDate on) {
690	        return new Claim(id, sheetId, personId, amount, date, note, status, number, settledDue, openedBy, stated, statedDue, corrects, dueBy, deferredUntil, proofs, proofsPhoto, splitFrom, lateEntry, on, ref, tags, waived, held);
691	    }
692	
693	    /**
694	     * Whether the claim is deferred on {@code today}: an OPEN claim deferred to a date the sheet's today has not reached
695	     * counts in no total, is not overdue, cannot be settled and is left unbound by a statement. While a statement binds
696	     * it the deferral waits: it counts and can be settled, and the deferral takes effect once the binding ends (on a
697	     * claim settled meanwhile too).
698	     */
699	    public boolean deferredOn(LocalDate today) {
700	        return (status == ClaimStatus.OPEN || status == ClaimStatus.SETTLED) && !stated && deferredUntil != null
701	                && (today == null || today.isBefore(deferredUntil));
702	    }
703	
704	    /** How many of its proofs are of the kind (receipt or photo). */
705	    public int proofsOf(String kind) {
706	        return "photo".equals(kind) ? proofsPhoto : "receipt".equals(kind) ? proofs - proofsPhoto : 0;
707	    }
708	
709	    /** A correction: its due is its amount times the rate, with no floor and no late charge. */
710	    public boolean isCorrection() {
711	        return amount.signum() < 0;
712	    }
713	}
