    }

    /** The alert threshold, with two decimals; null when alerts are off. */
    public BigDecimal alertThreshold(String sheetId) {
        String value = get(sheetId, ALERT_THRESHOLD);
        return value.isEmpty() ? null : new BigDecimal(value).setScale(2);
    }

    /**
     * How the claim's live figures round: by the rounding mode in force on its date when there is one, else half up when it is
     * dated before the policy date, half to even on or after it. A correction rounds by the date of the claim it corrects.
     */
    public RoundingMode rounding(Claim claim) {
        LocalDate date = claim.date();
        if (claim.isCorrection() && claim.corrects() != null) {
            Claim corrected = claims.findByNumber(claim.sheetId(), claim.personId(), claim.corrects());
            if (corrected != null) {
                date = corrected.date();
            }
        }
        String mode = on(claim.sheetId(), ROUNDING, date);
        if (!mode.isEmpty()) {
            return mode.equals("half-up") ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
        }
        return date.isBefore(policyDate(claim.sheetId())) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }

    /** The claim's rate figure at the rate (a percent): its amount times the rate, rounded by {@link #rounding}, not yet floored; null (no rate) stays null. */
    public BigDecimal live(Claim claim, BigDecimal rate) {
        return rate == null ? null : claim.amount().multiply(rate).movePointLeft(2).setScale(2, rounding(claim));
    }

    /**
     * A claim's live due from its rate figure: the figure raised to the floor in force on the claim's date ({@link #floored}), then its
     * late charge, worked out on that floored figure, added on top. An open (OPEN or PENDING) claim whose due-by (fixed when it was made) plus
     * its grade's grace ({@link #overdueFrom}) is before {@code today} gains, for every full 30 days it is overdue, the late percent in force on
     * that boundary date (the due-by plus the grace plus 30, 60, 90 ... days)
     * of the figure plus the charges of the boundaries before it (compounding), each charge rounded by {@link #rounding}, the charges added up; a boundary whose percent is 0.00 adds nothing.
     * The charge follows the sheet's today; a statement binds the due this works out (callers use the bound due as it is); null (no figure) stays null.
     * A correction has no late charge and no floor, and a deferred claim no late charge (it is not overdue until the sheet's today reaches its date).
     * A waived claim has no late charge, whatever its overdue state.
     */
    public BigDecimal withLate(Claim claim, BigDecimal figure, LocalDate today) {
        return lateAdded(claim, floored(claim, figure), today);
    }

    /** The (floored) figure with the claim's late charge on {@code today} added on top (see {@link #withLate}). */
    private BigDecimal lateAdded(Claim claim, BigDecimal figure, LocalDate today) {
        if (figure == null || !claim.status().isOpen() || claim.isCorrection() || claim.deferredOn(today) || claim.waived()) {
            return figure;
        }
        LocalDate dueBy = overdueFrom(claim);
        if (!dueBy.isBefore(today)) {
            return figure;
        }
        long periods = ChronoUnit.DAYS.between(dueBy, today) / 30;
        RoundingMode rounding = rounding(claim);
        BigDecimal total = figure;
        for (long n = 1; n <= periods; n++) {
            BigDecimal pct = latePct(claim.sheetId(), dueBy.plusDays(30 * n));
            if (pct.signum() != 0) {
                total = total.add(total.multiply(pct).movePointLeft(2).setScale(2, rounding));
            }
        }
        return total;
    }

    /** The claim's rate figure raised to the floor in force on the claim's date; null (no due) stays null, and a correction's due has no floor. */
    public BigDecimal floored(Claim claim, BigDecimal due) {
        return due == null || claim.isCorrection() ? due : due.max(floor(claim.sheetId(), claim.date()));
    }

    /** The key an action's permitted roles are kept under: perm-<action>. */
    public static String permKey(String action) {
        return "perm-" + action;
    }

    /** The roles an action is permitted to, as saved: a comma separated list, or "" for the standing rule. */
    public String perm(String sheetId, String action) {
        return get(sheetId, permKey(action));
    }

    /** The standing rule: reassign and reopen by steward; open, settle, void, close and today by clerk and steward (anyone but a viewer). */
    private static List<String> standing(String action) {
        return action.equals("reassign") || action.equals("reopen") ? List.of(STEWARD) : ROLES;
    }

    /** Whether the user's role may take the action on the sheet: as the permission matrix has it, else by the standing rule. */
    public boolean permits(String sheetId, String action, String user) {
        String saved = perm(sheetId, action);
        List<String> roles = saved.isEmpty() ? standing(action) : List.of(saved.split(","));
        String role = role(sheetId, user);
        // A restricted user may do what a clerk may: the role narrows only the people list they see.
        return roles.contains(RESTRICTED.equals(role) ? CLERK : role);
    }

    /** The sheet's roles, by user name. */
    public List<Role> roles(String sheetId) {
        return jdbc.query("SELECT * FROM " + AsOf.table("sheet_role") + " WHERE sheet_id = ? ORDER BY user_name",
                (rs, n) -> new Role(rs.getString("sheet_id"), rs.getString("user_name"), rs.getString("role")), sheetId);
    }

    /** The role the user acts in: steward while the sheet's today is inside a delegation to them, else the role the sheet gave them. */
    public String role(String sheetId, String user) {
        return delegator(sheetId, user) != null ? STEWARD : givenRole(sheetId, user);
    }

    /** The steward who delegated the steward role to the user for the sheet's today; null when none did. */
    public String delegator(String sheetId, String user) {
        return delegator(sheetId, user, sheets.today(sheetId));
    }

    /** The steward who delegated the steward role to the user for {@code on}; null when none did. */
    public String delegator(String sheetId, String user, java.time.LocalDate on) {
        String name = user == null ? "" : user.trim();
        return name.isEmpty() ? null : delegations.delegator(sheetId, name, on);
    }

    /** The role the sheet gave the user: clerk unless it gave them another (a delegation aside). */
    public String givenRole(String sheetId, String user) {
        List<String> roles = jdbc.queryForList("SELECT role FROM " + AsOf.table("sheet_role") + " WHERE sheet_id = ? AND user_name = ?",
                String.class, sheetId, user);
        return roles.isEmpty() ? CLERK : roles.get(0);
    }

    /** Whether the user is a viewer on the sheet, and so may change nothing. */
    public boolean isViewer(String sheetId, String user) {
        return VIEWER.equals(role(sheetId, user == null ? "" : user.trim()));
    }

    public void save(Role role) {
        jdbc.update("MERGE INTO sheet_role (sheet_id, user_name, role) KEY (sheet_id, user_name) VALUES (?, ?, ?)",
                role.sheetId(), role.user(), role.role());
    }
}
package net.officefloor.hq.app.claim;

/**
 * Where a claim is in its life: DRAFT, then OPEN, then SETTLED; a DRAFT, OPEN or PENDING claim can be VOID, and a
 * SETTLED one too, by a steward within {@link #VOID_SETTLED_DAYS} days of its settlement. A clerk's
 * settle of a claim whose due is above the clerk limit makes it PENDING instead, until a steward approves it (SETTLED)
 * or rejects it (back to OPEN). A DRAFT claim can be DELETED, counting nowhere, and restored to DRAFT on the same
 * sheet's today it was deleted. Opening a DRAFT claim whose due is above the review threshold in force on its date makes it
 * REVIEW instead, counting in no total, until a steward's review makes it OPEN; a REVIEW claim can be VOID.
 */
public enum ClaimStatus {
    DRAFT, OPEN, PENDING, SETTLED, VOID, DELETED, REVIEW;

    /** How many days after its settlement (by the sheet's today) a steward may still void a SETTLED claim. */
    public static final int VOID_SETTLED_DAYS = 7;

    /** Whether a claim in this status may move to {@code next}. */
    public boolean allows(ClaimStatus next) {
        return switch (next) {
            case OPEN -> this == DRAFT || this == PENDING || this == REVIEW;
            case PENDING -> this == OPEN;
            case SETTLED -> this == OPEN || this == PENDING;
            case VOID -> this == DRAFT || this == OPEN || this == PENDING || this == SETTLED || this == REVIEW;
            case REVIEW -> this == DRAFT;
            case DRAFT -> this == DELETED;
            case DELETED -> this == DRAFT;
        };
    }

    /** Whether a claim in this status is open: OPEN, or PENDING, which is handled like OPEN in every total. */
    public boolean isOpen() {
        return this == OPEN || this == PENDING;
    }

    /** Whether a claim in this status counts toward the totals: an open or a SETTLED one. */
    public boolean counts() {
        return isOpen() || this == SETTLED;
    }

    /** The audit event of a change from {@code from} to this status. */
    public String event(ClaimStatus from) {
        if (from == DELETED && this == DRAFT) {
            return "CLAIM_RESTORED";
        }
        if (from == REVIEW && this == OPEN) {
            return "CLAIM_REVIEWED";
        }
        if (from == PENDING) {
            return this == SETTLED ? "CLAIM_APPROVED" : this == OPEN ? "CLAIM_REJECTED" : event();
        }
        return event();
    }

    /** The audit event of a change to this status. */
    public String event() {
        return switch (this) {
            case OPEN -> "CLAIM_OPENED";
            case PENDING -> "CLAIM_PENDING";
            case SETTLED -> "CLAIM_SETTLED";
            case VOID -> "CLAIM_VOIDED";
            case DRAFT -> "CLAIM_DRAFTED";
            case DELETED -> "CLAIM_DELETED";
            case REVIEW -> "CLAIM_REVIEW";
        };
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * A claim made by a person on a sheet. {@code amount} is 0.00 or more, in two decimals. {@code number}
 * is given when the claim is settled or approved, and kept by a void (null before; a claim numbered on opening before keeps its number). {@code settledDue} is the due fixed
 * when it was settled (null when not settled, or settled while no rate of its grade applied on its date).
 * {@code openedBy} is the user who opened it (null when never opened). {@code stated} is whether its person's
 * last statement bound it, at {@code statedDue} (null when it had no figure then). A claim with a negative amount is a
 * correction: {@code corrects} is the number of the SETTLED claim of the same person it corrects (null for any other claim).
 * {@code dueBy} is fixed when the claim is made, the terms-th business day after its date (see {@code Holidays#dueBy}), and kept when its terms or its date change later; a holiday added later on or before it works it out again from its date with the terms it was fixed with (see {@code Claims#refixDueBys}); one a steward set directly stays as set (see {@code Claims#setDueBy}).
 * {@code deferredUntil} is the date an OPEN claim was deferred to (null when never deferred).
 * {@code proofs} is how many proofs it has been given (0 for none), {@code proofsPhoto} how many of them are photos (the rest are receipts).
 * {@code splitFrom} is the number of the claim it was split off (null for any other claim).
 * {@code lateEntry} is whether it was added while the period its due-by falls in was soft-closed.
 * {@code remindedOn} is the last sheet's today a reminder was written for it (null when never reminded).
 * {@code ref} is its external reference, unique on the sheet without regard to case (null when it has none).
 * {@code tags} are its tags, trimmed, lower-cased, without repeats and sorted (empty for none).
 * {@code waived} is whether a steward waived its late charge: it bears none from then on.
 * {@code held} is whether it is held: while OPEN or PENDING and not bound by a statement it counts in no live due figure (it still counts in claimed).
 */
public record Claim(long id, String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
        ClaimStatus status, String number, BigDecimal settledDue, String openedBy, boolean stated,
        BigDecimal statedDue, String corrects, LocalDate dueBy, LocalDate deferredUntil, int proofs, int proofsPhoto,
        String splitFrom, boolean lateEntry, LocalDate remindedOn, String ref, java.util.List<String> tags, boolean waived, boolean held) {

    public Claim with(ClaimInput input, LocalDate date) {
        return new Claim(id, sheetId, personId, input.amount(), date, input.note(), status, number, settledDue, openedBy, stated, statedDue, input.corrects(), dueBy, deferredUntil, proofs, proofsPhoto, splitFrom, lateEntry, remindedOn, input.ref(), input.tags(), waived, held);
    }

    public Claim withStatus(ClaimStatus status, String number, BigDecimal settledDue, String openedBy) {
        return new Claim(id, sheetId, personId, amount, date, note, status, number, settledDue, openedBy, stated, statedDue, corrects, dueBy, deferredUntil, proofs, proofsPhoto, splitFrom, lateEntry, remindedOn, ref, tags, waived, held);
    }

    /** The claim moved to another person: unbound from any statement, so live until their next one. */
    public Claim withPerson(long personId) {
        return new Claim(id, sheetId, personId, amount, date, note, status, number, settledDue, openedBy, false, null, corrects, dueBy, deferredUntil, proofs, proofsPhoto, splitFrom, lateEntry, remindedOn, ref, tags, waived, held);
    }

    /** The claim re-dated to {@code date}, numbered {@code number}. */
    public Claim withDate(LocalDate date, String number) {
        return new Claim(id, sheetId, personId, amount, date, note, status, number, settledDue, openedBy, stated, statedDue, corrects, dueBy, deferredUntil, proofs, proofsPhoto, splitFrom, lateEntry, remindedOn, ref, tags, waived, held);
    }

    /** The claim due by {@code dueBy}. */
    public Claim withDueBy(LocalDate dueBy) {
        return new Claim(id, sheetId, personId, amount, date, note, status, number, settledDue, openedBy, stated, statedDue, corrects, dueBy, deferredUntil, proofs, proofsPhoto, splitFrom, lateEntry, remindedOn, ref, tags, waived, held);
    }

    /** The claim deferred to {@code until}. */
    public Claim withDeferredUntil(LocalDate until) {
        return new Claim(id, sheetId, personId, amount, date, note, status, number, settledDue, openedBy, stated, statedDue, corrects, dueBy, until, proofs, proofsPhoto, splitFrom, lateEntry, remindedOn, ref, tags, waived, held);
    }

    /** The claim with {@code amount} as its amount, unbound from any statement (live until its person's next one). */
    public Claim withAmountUnbound(BigDecimal amount) {
        return new Claim(id, sheetId, personId, amount, date, note, status, number, settledDue, openedBy, false, null, corrects, dueBy, deferredUntil, proofs, proofsPhoto, splitFrom, lateEntry, remindedOn, ref, tags, waived, held);
    }

    /** The claim with {@code proofs} proofs, {@code proofsPhoto} of them photos. */
    public Claim withProofs(int proofs, int proofsPhoto) {
        return new Claim(id, sheetId, personId, amount, date, note, status, number, settledDue, openedBy, stated, statedDue, corrects, dueBy, deferredUntil, proofs, proofsPhoto, splitFrom, lateEntry, remindedOn, ref, tags, waived, held);
    }

    /** The claim with its late charge waived. */
    public Claim withWaived() {
