package net.officefloor.hq.app.claim;


public class RefuseClosedClaim {
    // A claim belongs to the period its due-by falls in: one due by a date inside a closed period cannot be edited,
    // opened, settled or voided.
    public void refuse(@Val Claim claim, Periods periods) throws ClaimInClosedPeriodException {
        Period closed = periods.closedOn(claim.sheetId(), claim.dueBy());
        if (closed != null) {
            throw new ClaimInClosedPeriodException("The period " + closed.name() + " is closed: its claims cannot change.");
        }
    }
}
package net.officefloor.hq.app.claim;


public class RefuseClosedNewInput {
    // A claim belongs to the period its due-by falls in: the due-by the claim being added would be fixed with (its date
    // — a blank date is the entry date, else the sheet's today — plus its person's terms in force on the sheet's today, moved past the sheet's holidays) must not be in a closed period.
    public void refuse(@PathVariable("sheetId") String sheetId, @Val ClaimInput input, @Val Person person,
            Settings settings, Holidays holidays, Periods periods) throws ClaimInClosedPeriodException {
        String sheet = sheetId.trim();
        LocalDate date = input.date() != null ? input.date() : settings.entryDate(sheet);
        check(periods, sheet, holidays.dueBy(sheet, date, person.termsNow(settings)));
    }

    /** Refuses a new claim due by {@code dueBy} when that falls inside a closed period. */
    static void check(Periods periods, String sheet, LocalDate dueBy) throws ClaimInClosedPeriodException {
        Period closed = periods.closedOn(sheet, dueBy);
        if (closed != null) {
            throw new ClaimInClosedPeriodException("The period " + closed.name() + " is closed: no claim due by "
                    + dueBy + " can be added.");
        }
    }
}
package net.officefloor.hq.app.claim;


public class RefuseRetiredInput {
    // The date a claim is being added to (a blank date is the entry date, else the sheet's today) must not be after its person's retirement,
    // nor strictly between the dates of one of their past retirements.
    public void refuse(@Val ClaimInput input, @Val Person person, Settings settings) throws ClaimAfterRetirementException {
        check(person, input.date() != null ? input.date() : settings.entryDate(person.sheetId()));
    }

    static void check(Person person, LocalDate date) throws ClaimAfterRetirementException {
        if (person != null && person.retired() && date.isAfter(person.retiredFrom())) {
            throw new ClaimAfterRetirementException(person.name() + " is retired from " + person.retiredFrom()
                    + ": no claim dated " + date + " can be added or edited.");
        }
        if (person != null) {
