    public Map<Long, BigDecimal> totals(String sheetId) {
        Map<Long, BigDecimal> out = new HashMap<>();
        for (PoolResponse pool : RespondWithPools.figure(sheetId, pools, people, settings, sheets, crews, Map.of(),
